(1, 'EB01-001', 'EB01-001', 'en', 'en', 'L', '2', NULL, 5000, NULL, 4, 1, 1, 'https://en.onepiece-cardgame.com/cardlist/?series=569201', '2024-05-03', 0, 'official', '{"uid":"EB01-001","id":"EB01-001","name":"Kouzuki Oden","rarity":"L","type":"LEADER","cost":null,"life":"4","attribute":"Slash","power":"5000","counter":"-","color":"Red/Green","block":"2","archetype":"Land of Wano/Kouzuki Clan","effect":"All of your {Land of Wano} type Character cards without a Counter have a +1000 Counter, according to the rules.\n[DON!! x1] [When Attacking] If you have a {Land of Wano} type Character with a cost of 5 or more, this Leader gains +1000 power until the start of your next turn.","trigger":"","image":"https://en.onepiece-cardgame.com/images/cardlist/card/EB01-001.png","sets":[{"id":"569201","name":"EXTRA BOOSTER -MEMORIAL COLLECTION- [EB-01]"}],"source":"https://en.onepiece-cardgame.com/cardlist/?series=569201","language":"en","sourceKind":"bandai","imageStatus":"official","spoiler":false,"releaseDate":"2024-05-03","legalBlocks":["2"]}'),
(2, 'EB01-001_p1', 'EB01-001', 'en', 'en', 'L', '2', NULL, 5000, NULL, 4, 1, 1, 'https://en.onepiece-cardgame.com/cardlist/?series=569201', '2024-05-03', 0, 'official', '{"uid":"EB01-001_p1","id":"EB01-001","name":"Kouzuki Oden","rarity":"L","type":"LEADER","cost":null,"life":"4","attribute":"Slash","power":"5000","counter":"-","color":"Red/Green","block":"2","archetype":"Land of Wano/Kouzuki Clan","effect":"All of your {Land of Wano} type Character cards without a Counter have a +1000 Counter, according to the rules.\n[DON!! x1] [When Attacking] If you have a {Land of Wano} type Character with a cost of 5 or more, this Leader gains +1000 power until the start of your next turn.","trigger":"","image":"https://en.onepiece-cardgame.com/images/cardlist/card/EB01-001_p1.png","sets":[{"id":"569201","name":"EXTRA BOOSTER -MEMORIAL COLLECTION- [EB-01]"}],"source":"https://en.onepiece-cardgame.com/cardlist/?series=569201","language":"en","sourceKind":"bandai","imageStatus":"official","spoiler":false,"releaseDate":"2024-05-03","legalBlocks":["2"]}'),
(3, 'EB01-001_p2', 'EB01-001', 'en', 'en', 'L', '2', NULL, 5000, NULL, 4, 1, 1, 'https://en.onepiece-cardgame.com/cardlist/?series=569202', '2024-05-03', 0, 'official', '{"uid":"EB01-001_p2","id":"EB01-001","name":"Kouzuki Oden","rarity":"L","type":"LEADER","cost":null,"life":"4","attribute":"Slash","power":"5000","counter":"-","color":"Red/Green","block":"2","archetype":"Land of Wano/Kouzuki Clan","effect":"All of your {Land of Wano} type Character cards without a Counter have a +1000 Counter, according to the rules.\n[DON!! x1] [When Attacking] If you have a {Land of Wano} type Character with a cost of 5 or more, this Leader gains +1000 power until the start of your next turn.","trigger":"","image":"https://en.onepiece-cardgame.com/images/cardlist/card/EB01-001_p2.png","sets":[{"id":"569202","name":"EXTRA BOOSTER -Anime 25th Collection- [EB-02]"}],"source":"https://en.onepiece-cardgame.com/cardlist/?series=569202","language":"en","sourceKind":"bandai","imageStatus":"official","spoiler":false,"releaseDate":"2024-05-03","legalBlocks":["2"]}'),
(4, 'EB01-002', 'EB01-002', 'en', 'en', 'R', '2', 5, 7000, NULL, NULL, 1, 1, 'https://en.onepiece-cardgame.com/cardlist/?series=569201', '2024-05-03', 0, 'official', '{"uid":"EB01-002","id":"EB01-002","name":"Izo","rarity":"R","type":"CHARACTER","cost":"5","life":null,"attribute":"Ranged","power":"7000","counter":"-","color":"Red","block":"2","archetype":"Land of Wano/Whitebeard Pirates","effect":"[On Play] Give up to 1 rested DON!! card to your Leader or 1 of your Characters.[On Your Opponent''s Attack] [Once Per Turn] You may trash 1 card from your hand: If your Leader has the {Land of Wano} or {Whitebeard Pirates} type, give up to 1 of your opponent''s Leader or Character cards −2000 power during this turn.","trigger":"","image":"https://en.onepiece-cardgame.com/images/cardlist/card/EB01-002.png","sets":[{"id":"569201","name":"EXTRA BOOSTER -MEMORIAL COLLECTION- [EB-01]"}],"source":"https://en.onepiece-cardgame.com/cardlist/?series=569201","language":"en","sourceKind":"bandai","imageStatus":"official","spoiler":false,"releaseDate":"2024-05-03","legalBlocks":["2"]}'),
