INSERT INTO printing_explanations (printing_id, language_code, summary, reading_guide, strategic_focus, preview_text, is_curated, details, generator_version) VALUES
(1, 'pt-BR', 'Kouzuki Oden é uma carta vermelha e verde da categoria Líder. Começa com 4 cartas de vida. Tem 5.000 de poder base.', 'As características impressas são Land of Wano e Kouzuki Clan. Elas podem ser exigidas por outras habilidades; não substituem a categoria da carta. O texto possui as seguintes janelas: ao declarar ataque. Confira os custos e condições de cada trecho. ', 'A carta que define o rumo do seu deck.', '4 de vida · 5.000 de poder. Ao declarar ataque.', 0, '{"intro":"Kouzuki Oden é uma carta vermelha e verde da categoria Líder. Começa com 4 cartas de vida. Tem 5.000 de poder base.","reading":"As características impressas são Land of Wano e Kouzuki Clan. Elas podem ser exigidas por outras habilidades; não substituem a categoria da carta. O texto possui as seguintes janelas: ao declarar ataque. Confira os custos e condições de cada trecho. ","focus":"A carta que define o rumo do seu deck.","preview":"4 de vida · 5.000 de poder. Ao declarar ataque.","curated":null,"hints":["As cores deste Líder orientam a construção do deck. Confira também qualquer regra especial escrita no efeito.","O trecho DON!! x1 exige essa quantidade de DON!! atribuída à carta para a condição indicada. Não significa pagar automaticamente esse número."],"timings":[{"key":"When Attacking","label":"Ao declarar ataque","explanation":"A ativação ocorre na declaração do ataque, não somente depois de causar dano."}],"keywords":[],"characteristics":["Land of Wano","Kouzuki Clan"],"rarity":"Líder"}', 'frontend-v0.4'),
(2, 'pt-BR', 'Kouzuki Oden é uma carta vermelha e verde da categoria Líder. Começa com 4 cartas de vida. Tem 5.000 de poder base.', 'As características impressas são Land of Wano e Kouzuki Clan. Elas podem ser exigidas por outras habilidades; não substituem a categoria da carta. O texto possui as seguintes janelas: ao declarar ataque. Confira os custos e condições de cada trecho. ', 'A carta que define o rumo do seu deck.', '4 de vida · 5.000 de poder. Ao declarar ataque.', 0, '{"intro":"Kouzuki Oden é uma carta vermelha e verde da categoria Líder. Começa com 4 cartas de vida. Tem 5.000 de poder base.","reading":"As características impressas são Land of Wano e Kouzuki Clan. Elas podem ser exigidas por outras habilidades; não substituem a categoria da carta. O texto possui as seguintes janelas: ao declarar ataque. Confira os custos e condições de cada trecho. ","focus":"A carta que define o rumo do seu deck.","preview":"4 de vida · 5.000 de poder. Ao declarar ataque.","curated":null,"hints":["As cores deste Líder orientam a construção do deck. Confira também qualquer regra especial escrita no efeito.","O trecho DON!! x1 exige essa quantidade de DON!! atribuída à carta para a condição indicada. Não significa pagar automaticamente esse número."],"timings":[{"key":"When Attacking","label":"Ao declarar ataque","explanation":"A ativação ocorre na declaração do ataque, não somente depois de causar dano."}],"keywords":[],"characteristics":["Land of Wano","Kouzuki Clan"],"rarity":"Líder"}', 'frontend-v0.4'),
(3, 'pt-BR', 'Kouzuki Oden é uma carta vermelha e verde da categoria Líder. Começa com 4 cartas de vida. Tem 5.000 de poder base.', 'As características impressas são Land of Wano e Kouzuki Clan. Elas podem ser exigidas por outras habilidades; não substituem a categoria da carta. O texto possui as seguintes janelas: ao declarar ataque. Confira os custos e condições de cada trecho. ', 'A carta que define o rumo do seu deck.', '4 de vida · 5.000 de poder. Ao declarar ataque.', 0, '{"intro":"Kouzuki Oden é uma carta vermelha e verde da categoria Líder. Começa com 4 cartas de vida. Tem 5.000 de poder base.","reading":"As características impressas são Land of Wano e Kouzuki Clan. Elas podem ser exigidas por outras habilidades; não substituem a categoria da carta. O texto possui as seguintes janelas: ao declarar ataque. Confira os custos e condições de cada trecho. ","focus":"A carta que define o rumo do seu deck.","preview":"4 de vida · 5.000 de poder. Ao declarar ataque.","curated":null,"hints":["As cores deste Líder orientam a construção do deck. Confira também qualquer regra especial escrita no efeito.","O trecho DON!! x1 exige essa quantidade de DON!! atribuída à carta para a condição indicada. Não significa pagar automaticamente esse número."],"timings":[{"key":"When Attacking","label":"Ao declarar ataque","explanation":"A ativação ocorre na declaração do ataque, não somente depois de causar dano."}],"keywords":[],"characteristics":["Land of Wano","Kouzuki Clan"],"rarity":"Líder"}', 'frontend-v0.4'),
(4, 'pt-BR', 'Izo é uma carta vermelha da categoria Personagem. Seu custo impresso é 5 DON!!. Entra com 7.000 de poder base.', 'As características impressas são Land of Wano e Whitebeard Pirates. Elas podem ser exigidas por outras habilidades; não substituem a categoria da carta. O texto possui as seguintes janelas: ao entrar em jogo; quando o oponente ataca. Confira os custos e condições de cada trecho. ', 'Uma peça para conhecer antes de levar ao campo.', '5 DON!! · 7.000 de poder. Sem Counter numérico.', 0, '{"intro":"Izo é uma carta vermelha da categoria Personagem. Seu custo impresso é 5 DON!!. Entra com 7.000 de poder base.","reading":"As características impressas são Land of Wano e Whitebeard Pirates. Elas podem ser exigidas por outras habilidades; não substituem a categoria da carta. O texto possui as seguintes janelas: ao entrar em jogo; quando o oponente ataca. Confira os custos e condições de cada trecho. ","focus":"Uma peça para conhecer antes de levar ao campo.","preview":"5 DON!! · 7.000 de poder. Sem Counter numérico.","curated":null,"hints":["Sem Counter numérico impresso neste registro: não conte com esta carta para aumentar a defesa pelo Counter de Personagem.","Há um limite de uma vez por turno no efeito indicado; ele não transforma todas as habilidades da carta em uma única ativação."],"timings":[{"key":"On Play","label":"Ao entrar em jogo","explanation":"Verifique os custos e condições do efeito que se ativa quando a carta é jogada."},{"key":"On Your Opponent''s Attack","label":"Quando o oponente ataca","explanation":"A declaração de ataque do adversário é a janela mencionada pelo efeito."}],"keywords":[],"characteristics":["Land of Wano","Whitebeard Pirates"],"rarity":"Rara"}', 'frontend-v0.4'),
(5, 'pt-BR', 'Kid & Killer é uma carta vermelha da categoria Personagem. Seu custo impresso é 4 DON!!. Entra com 5.000 de poder base.', 'As características impressas são Supernovas e Kid Pirates. Elas podem ser exigidas por outras habilidades; não substituem a categoria da carta. O texto possui as seguintes janelas: ao declarar ataque. Confira os custos e condições de cada trecho. ', 'Uma peça para conhecer antes de levar ao campo.', '4 DON!! · 5.000 de poder. Sem Counter numérico · Rush.', 0, '{"intro":"Kid & Killer é uma carta vermelha da categoria Personagem. Seu custo impresso é 4 DON!!. Entra com 5.000 de poder base.","reading":"As características impressas são Supernovas e Kid Pirates. Elas podem ser exigidas por outras habilidades; não substituem a categoria da carta. O texto possui as seguintes janelas: ao declarar ataque. Confira os custos e condições de cada trecho. ","focus":"Uma peça para conhecer antes de levar ao campo.","preview":"4 DON!! · 5.000 de poder. Sem Counter numérico · Rush.","curated":null,"hints":["Sem Counter numérico impresso neste registro: não conte com esta carta para aumentar a defesa pelo Counter de Personagem."],"timings":[{"key":"When Attacking","label":"Ao declarar ataque","explanation":"A ativação ocorre na declaração do ataque, não somente depois de causar dano."}],"keywords":[{"key":"Rush","title":"Rush","text":"Permite que um Personagem ataque no turno em que é jogado. Não ignora a proibição de atacar no primeiro turno de cada jogador."}],"characteristics":["Supernovas","Kid Pirates"],"rarity":"Rara"}', 'frontend-v0.4'),
(6, 'pt-BR', 'Kid & Killer é uma carta vermelha da categoria Personagem. Seu custo impresso é 4 DON!!. Entra com 5.000 de poder base.', 'As características impressas são Supernovas e Kid Pirates. Elas podem ser exigidas por outras habilidades; não substituem a categoria da carta. O texto possui as seguintes janelas: ao declarar ataque. Confira os custos e condições de cada trecho. ', 'Uma peça para conhecer antes de levar ao campo.', '4 DON!! · 5.000 de poder. Sem Counter numérico · Rush.', 0, '{"intro":"Kid & Killer é uma carta vermelha da categoria Personagem. Seu custo impresso é 4 DON!!. Entra com 5.000 de poder base.","reading":"As características impressas são Supernovas e Kid Pirates. Elas podem ser exigidas por outras habilidades; não substituem a categoria da carta. O texto possui as seguintes janelas: ao declarar ataque. Confira os custos e condições de cada trecho. ","focus":"Uma peça para conhecer antes de levar ao campo.","preview":"4 DON!! · 5.000 de poder. Sem Counter numérico · Rush.","curated":null,"hints":["Sem Counter numérico impresso neste registro: não conte com esta carta para aumentar a defesa pelo Counter de Personagem."],"timings":[{"key":"When Attacking","label":"Ao declarar ataque","explanation":"A ativação ocorre na declaração do ataque, não somente depois de causar dano."}],"keywords":[{"key":"Rush","title":"Rush","text":"Permite que um Personagem ataque no turno em que é jogado. Não ignora a proibição de atacar no primeiro turno de cada jogador."}],"characteristics":["Supernovas","Kid Pirates"],"rarity":"Rara"}', 'frontend-v0.4'),
